entries[1260825] = { ["name"] = "Trap: Void Sphere [original]", ["text"] = "5 sec cast 5 sec cooldown\nCast Time: 5 seconds.\nTrap Cooldown: 5 seconds.\n\nCreates a Void Sphere that persists for 15 sec. The sphere behaves differently for Hiders and Seekers.\n\nHiders who make contact with the sphere are propelled forwards up to 30 yards.\n\nSeekers who make contact with the sphere are repelled backwards up to 20 yards.\n\nDon't worry--the cold emptiness of the void lasts for but a moment. Soon, your guts will be be wrenched in one direction or another, and it will all be over before you know it." }
