entries[1261336] = { ["name"] = "Preyseeker's Hubris", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Larger mana wyrms are sometimes used as mounts by Blood Elves, but are more frequently kept as status symbols.\"\nVendor:\nConstruct E'nui\nZone:\nSilvermoon City\nCost:\n2000" }
entries[1261337] = { ["name"] = "Preyseeker's Wrath", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Mana wyrms that are large and strong enough to support full barding and rider are quite rare and highly prized.\"\nVendor:\nConstruct E'nui\nZone:\nSilvermoon City\nCost:\n2550" }
entries[1261338] = { ["name"] = "Preyseeker's Nightmare", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Golden mana wyrms are an uncommon mutation. Some of Astalor's side experiments have included efforts to increase their population..\"\nAchievement:\nPrey: Nightmare Mode III\nCategory:\nPrey" }
entries[1261339] = { ["name"] = "Cosmic Portal", ["text"] = "300 yd range\nInstant\nAlleria rips open a portal, calling forth a void being from the past." }
entries[1261340] = { ["name"] = "Draenei Holo-Path", ["text"] = "2 sec cast\nTools: Runed Enchanting Rod\nReagents:\nOlemba Lumber (20), Large Prismatic Shard (4), Greater Planar Essence (4), Arcane Dust (12)\nCreate a Draenei Holo-Path, which can be placed in your house or sold on the Auction House.\nProfession Trainer:\nOutland Enchanting (60)\nCost:\n2\n50\n\n1\nDraenei Holo-Path\nHousing Decor\nBinds when used\nUse: Add this Decor to your House Chest." }
entries[1261341] = { ["name"] = "Mandate of Sacred Death", ["text"] = "Unlimited range\nInstant\nWhen your delve companion casts Tools of the Trade , a Sacred Mandate is bestowed upon party members granting their harmful spells and abilities a [source value]% chance to deal 1% of the target's maximum health as additional Holy damage per Mandate.\n\nCan only occur once per target every 2 sec.\n\nTools of the Trade\nValeera uses her gathering tools to help players find additional gold, ore, herbs, fish, leathers, and treasures.", ["unresolvedValues"] = true }
