entries[1261347] = { ["name"] = "Bronze Banner of the Exiled", ["text"] = "2 sec cast\nTools: Blacksmith Hammer\nReagents:\nOlemba Lumber (20), Khorium Bar (8), Primal Earth (4), Primal Mooncloth (2)\nCreate a Bronze Banner of the Exiled, which can be placed in your house or sold on the Auction House.\nProfession Trainer:\nOutland Blacksmithing (60)\nCost:\n2\n50\n\n3\nBronze Banner of the Exiled\nHousing Decor\nBinds when used\nUse: Add this Decor to your House Chest." }
entries[1261348] = { ["name"] = "Blessed Amani Burrower", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"A creature blessed by the wilds, it moves with the steadfast spirit and gentle strength the Amani hold sacred.\"\nVendor:\nChel the Chip\nFeature:\nAbundance\nCost:\n1600" }
entries[1261349] = { ["name"] = "Giganto Manis", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Whispers tell of the Giganto Manis, a titanic creature said to dwell within Azeroth's very veins. Those who claim to have seen it speak of claws vast enough to pierce a dragon's heart, and sharp enough to carve through the finest armor forged by mortal hands.\"\nAchievement:\nGlory of the Midnight Delver" }
entries[1261351] = { ["name"] = "Witherbark Pango", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"This rather rambunctious Pango escaped from the Witherbark Tribe after having its armor affixed. Finders keepers!\"\nDrop:\nZul'Aman Rare Creatures" }
